59	bool alarm_model_remove_alarm(int index) {
60	    if (index < 0 || index >= MAX_ALARM_COUNT) return false;
61	    
62	    // 将后面的闹钟前移
63	    for (int i = index; i < MAX_ALARM_COUNT - 1; i++) {
64	        alarm_model.alarms[i] = alarm_model.alarms[i + 1];
65	    }
66	    
67	    alarm_model.alarm_count--;
68	    return true;
69	}
