71	void alarm_model_select_alarm(int index, bool selected) {
72	    if (index < 0 || index >= MAX_ALARM_COUNT) return;
73	    
74	    if (selected && !alarm_model.alarms[index].selected) {
75	        alarm_model.del_alarm_count++;
76	    } else if (!selected && alarm_model.alarms[index].selected) {
77	        alarm_model.del_alarm_count--;
78	    }
79	    
80	    alarm_model.alarms[index].selected = selected;
81	}
