81	/* 根据开关状态刷新闹钟卡片配色：开启→橙底橙边+橙色时间；关闭→整体半透+白色时间 */
82	static void apply_alarm_item_style(int idx, bool is_on) {
83	    if (idx < 0 || idx >= MAX_ALARM_COUNT) return;
84	    lv_obj_t * alarm_item = alarm_view.alarm_containers[idx];
85	    lv_obj_t * sw = alarm_view.alarm_switches[idx];
86	    if (!alarm_item) return;
87	    /* content 是 alarm_item 的第一个子对象 */
88	    lv_obj_t * content = lv_obj_get_child(alarm_item, 0);
89	    if (!content) return;
90	    /* 时间标签是 content 的第一个子对象 */
91	    lv_obj_t * alarm_time = lv_obj_get_child(content, 0);
92	
93	    if (is_on) {
94	        /* 开启态: 橙底 rgba(255,165,2,0.08) + 橙边 rgba(255,165,2,0.3) + 橙色时间 */
95	        lv_obj_set_style_bg_color(content, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
96	        lv_obj_set_style_bg_opa(content, 20, LV_PART_MAIN);
97	        lv_obj_set_style_border_color(content, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
98	        lv_obj_set_style_border_opa(content, LV_OPA_30, LV_PART_MAIN);
99	        lv_obj_set_style_opa(content, LV_OPA_COVER, LV_PART_MAIN);
100	        if (alarm_time) lv_obj_set_style_text_color(alarm_time, lv_color_make(0xFF, 0xA5, 0x02), LV_PART_MAIN);
101	    } else {
102	        /* 关闭态: 灰底 + 1px 灰边 + 整体半透明 opacity:0.5 + 白色时间 */
103	        lv_obj_set_style_bg_color(content, lv_color_white(), LV_PART_MAIN);
104	        lv_obj_set_style_bg_opa(content, 15, LV_PART_MAIN);
105	        lv_obj_set_style_border_color(content, lv_color_white(), LV_PART_MAIN);
106	        lv_obj_set_style_border_opa(content, 31, LV_PART_MAIN);
107	        lv_obj_set_style_opa(content, LV_OPA_50, LV_PART_MAIN);
108	        if (alarm_time) lv_obj_set_style_text_color(alarm_time, lv_color_white(), LV_PART_MAIN);
109	    }
110	    if (sw) {
111	        if (is_on) lv_obj_add_state(sw, LV_STATE_CHECKED);
112	        else lv_obj_clear_state(sw, LV_STATE_CHECKED);
113	    }
114	    lv_obj_invalidate(alarm_item);
115	}
