448	void alarm_view_restore_alarms_display(void)
449	{
450	    AlarmModel *model = get_alarm_model();
451	    LV_LOG_USER("恢复，闹钟数量为：%d", model ->alarm_count);
452	
453	    //清除现有的UI（异步删除，避免在事件回调中删除当前正在处理的对象导致卡死）
454	    for (int i = 0; i < MAX_ALARM_COUNT; i++) {
455	        if (alarm_view.alarm_containers[i]) {
456	            lv_obj_delete_async(alarm_view.alarm_containers[i]);
457	            alarm_view.alarm_containers[i] = NULL;
458	            alarm_view.alarm_switches[i] = NULL;
459	            alarm_view.alarm_checkboxes[i] = NULL;
460	        }
461	    }
462	    //重创建所有保存的闹钟UI
463	    for (int i = 0; i < model->alarm_count; i++) {
464	        LV_LOG_USER("重新创建闹钟UI: 索引=%d, 时间=%s", i, model->alarms[i].time);
465	        alarm_view_create_alarm(model->alarms[i].time, i);
466	    }
467	    
468	    alarm_view_update_alarm_list();
469	}
