957	void alarm_view_update_alarm_list() {
958	    LV_LOG_USER("进入alarm_view_update_alarm_list\n");
959	    AlarmModel* model = get_alarm_model();
960	    LV_LOG_USER("model->alarm_count:%d\n", model->alarm_count);
961	    if (model->alarm_count == 0) {
962	        lv_obj_remove_flag(alarm_view.clock_img, LV_OBJ_FLAG_HIDDEN);
963	        lv_obj_remove_flag(alarm_view.no_clock_label, LV_OBJ_FLAG_HIDDEN);
964	        lv_obj_add_flag(alarm_view.alarm_container, LV_OBJ_FLAG_HIDDEN);
965	    } else {
966	        lv_obj_add_flag(alarm_view.clock_img, LV_OBJ_FLAG_HIDDEN);
967	        lv_obj_add_flag(alarm_view.no_clock_label, LV_OBJ_FLAG_HIDDEN);
968	        lv_obj_remove_flag(alarm_view.alarm_container, LV_OBJ_FLAG_HIDDEN);
969	        LV_LOG_USER("操作成功\n");
970	    }
971	    
972	    if (model->long_pressed) {
973	        for (int i = 0; i < MAX_ALARM_COUNT; i++) {
974	            if(alarm_view.alarm_containers[i] != NULL){
975	                lv_obj_add_flag(alarm_view.alarm_switches[i], LV_OBJ_FLAG_HIDDEN);
976	                lv_obj_remove_flag(alarm_view.alarm_checkboxes[i], LV_OBJ_FLAG_HIDDEN);
977	            }
978	        }
979	        lv_obj_add_flag(alarm_view.btn_addClock, LV_OBJ_FLAG_HIDDEN);
980	        lv_obj_remove_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_HIDDEN);
981	        
982	        if (model->del_alarm_count == 0) {
983	            lv_obj_remove_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_CLICKABLE);
984	            lv_obj_set_style_bg_color(alarm_view.del_sel_btn, lv_color_make(36, 32, 35), LV_PART_MAIN);
985	        } else {
986	            lv_obj_add_flag(alarm_view.del_sel_btn, LV_OBJ_FLAG_CLICKABLE);
987	            lv_obj_set_style_bg_color(alarm_view.del_sel_btn, lv_color_make(32, 149, 246), LV_PART_MAIN);
