269	static void watch_sys_gesture_event_cb(lv_event_t *e)
270	{
271	    lv_event_code_t code = lv_event_get_code(e);
272	    lv_indev_t *indev = lv_indev_active();
273	    if (!indev) return;
274	
275	    lv_dir_t dir = lv_indev_get_gesture_dir(indev);
276	
277	    switch (code)
278	    {
279	    case LV_EVENT_GESTURE:
280	        if (dir == LV_DIR_LEFT)
281	        {
282	            if (!strcmp(mpd->current_page, HOME_PAGE))
283	            {
284	                g_prev_page = PAGE_HOME;
285	
286	                /* 先建好列表（ui_bg 实色盖满整屏），再隐藏表盘——
287	                 * 顺序不能反：先 hide 会露出黑底直到列表盖上来（黑屏）；
288	                 * 列表已就位盖满后再 hide 表盘只是省绘制，用户无感知，且无两层渲染卡顿。 */
289	                mpd->appListCenter = lv_obj_create(mpd->watchScr);
290	                app_launcher_create(mpd->appListCenter);
291	                watch_hide();
292	                g_current_page = PAGE_APPLIST;
293	                strcpy(mpd->current_page, APPS_PAGE);
294	            }
295	            else
296	            {
297	                bool is_home_page = !strcmp(mpd->current_page, HOME_PAGE);
298	                LV_LOG_USER("LV_DIR_LEFT + currentPage: %s, is_home_page %d \n", mpd->current_page, is_home_page);
299	            }
300	        }
301	        if (dir == LV_DIR_RIGHT)
302	        {
303	            LV_LOG_USER("LV_DIR_RIGHT  currentPage: %s \n", mpd->current_page);
304	            if (!strcmp(mpd->current_page, HOME_PAGE))
305	            {
306	                LV_LOG_USER("LV_DIR_RIGHT currentPage: %s  \n", mpd->current_page);
307	            }
308	            else
309	            {
310	                LV_LOG_USER("Before LV_DIR_RIGHT currentPage: %s %d \n", mpd->current_page, (mpd->appListCenter != NULL));
311	                if (mpd->appListCenter != NULL) {
312	                    lv_anim_delete(mpd->appListCenter, anim_translate_y_cb);
313	                    applist_hide_page();   /* 删列表 ui_bg 子树 + 清静态指针 */
314	                    lv_obj_delete(mpd->appListCenter);
315	                    mpd->appListCenter = NULL;
316	                }
317	
318	                /* 恢复表盘：取消 HIDDEN（timer 一直走，秒针已是当前角度，直接显示无跳动） */
319	                watch_show();
320	                watch_show();
321	                g_current_page = PAGE_HOME;
322	
323	                strcpy(mpd->current_page, HOME_PAGE);
324	            }
325	        }
326	        break;
327	    default:
328	        break;
329	    }
330	}
